INSERT INTO public.recipes (slug, name, description, cuisine, category, country, diet_tags, meal_type, cooking_time_minutes, difficulty, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, fun_fact, is_featured) VALUES
('cape-malay-bobotie','Cape Malay Bobotie','South Africa''s beloved spiced mince bake with a golden egg custard top — sweet, savoury and aromatic all at once.','South African','Dinner','South Africa',ARRAY['Gluten-Free'],'Dinner',55,'Medium',6,420,28,24,24,'[{"name":"Beef mince","quantity":"800 g"},{"name":"Onions, finely chopped","quantity":"2"},{"name":"Garlic cloves, crushed","quantity":"2"},{"name":"Curry powder","quantity":"2 tbsp"},{"name":"Turmeric","quantity":"1 tsp"},{"name":"White bread soaked in milk","quantity":"2 slices"},{"name":"Milk","quantity":"250 ml"},{"name":"Eggs","quantity":"2"},{"name":"Apricot jam","quantity":"2 tbsp"},{"name":"Raisins","quantity":"60 g"},{"name":"Bay leaves","quantity":"3"},{"name":"Salt and pepper","quantity":"to taste"}]'::jsonb,'["Soak the bread in half the milk, then squeeze out and mash.","Fry the onions until soft, add garlic, curry powder and turmeric and cook 1 minute.","Add the mince and brown, breaking it up with a fork.","Stir in the mashed bread, jam, raisins, salt and pepper. Cook 5 minutes.","Tip into a baking dish and tuck in the bay leaves.","Whisk the eggs with the remaining milk and pour over the mince.","Bake at 180°C for 35–40 minutes until the custard is set and golden.","Rest 10 minutes, then serve with yellow rice and chutney."]'::jsonb,'Bobotie was declared South Africa''s national dish and dates back to 17th-century Cape Malay kitchens.',true),
('chakalaka-with-pap','Chakalaka with Pap','A fiery vegetable relish of beans, peppers and carrots served over creamy maize pap — the soul of every South African braai.','South African','Dinner','South Africa',ARRAY['Vegan','Gluten-Free'],'Dinner',40,'Easy',4,310,9,52,8,'[{"name":"Onion, chopped","quantity":"1 large"},{"name":"Bell peppers, sliced","quantity":"2"},{"name":"Carrots, grated","quantity":"2"},{"name":"Curry powder","quantity":"1 tbsp"},{"name":"Chopped tomatoes","quantity":"400 g tin"},{"name":"Baked beans in tomato sauce","quantity":"400 g tin"},{"name":"Chili flakes","quantity":"1 tsp"},{"name":"Maize meal","quantity":"250 g"},{"name":"Water","quantity":"750 ml"},{"name":"Salt","quantity":"to taste"},{"name":"Oil","quantity":"2 tbsp"}]'::jsonb,'["For the pap: bring salted water to a boil, rain in the maize meal while stirring.","Reduce heat, cover and steam 30 minutes, stirring occasionally until smooth and stiff.","For the chakalaka: fry the onion in oil until soft.","Add peppers, carrots, curry powder and chili; cook 5 minutes.","Add the tomatoes and simmer 10 minutes until thick.","Stir in the baked beans and warm through. Season to taste.","Serve a generous scoop of pap with chakalaka spooned over."]'::jsonb,'Chakalaka was born in the townships of Johannesburg and every family guards its own spice mix.',true),
('chicken-bunny-chow','Chicken Bunny Chow','Durban''s iconic street food: fragrant chicken curry ladled into a hollowed-out loaf of white bread.','South African','Lunch','South Africa','{}','Lunch',50,'Medium',4,540,34,48,22,'[{"name":"Chicken thighs, boneless, cubed","quantity":"600 g"},{"name":"Onion, chopped","quantity":"1"},{"name":"Garlic and ginger paste","quantity":"1 tbsp"},{"name":"Garam masala","quantity":"2 tbsp"},{"name":"Chopped tomatoes","quantity":"400 g tin"},{"name":"Potatoes, cubed","quantity":"2"},{"name":"Curry leaves","quantity":"6"},{"name":"Unsliced white bread loaf","quantity":"1 small"},{"name":"Oil","quantity":"2 tbsp"},{"name":"Fresh coriander","quantity":"to garnish"},{"name":"Salt","quantity":"to taste"}]'::jsonb,'["Fry the onion and curry leaves in oil until golden.","Add garlic-ginger paste and garam masala; fry 1 minute.","Add the chicken and seal on all sides.","Add tomatoes and potatoes, season, and simmer 25 minutes until the potatoes are tender.","Cut the loaf into quarters and hollow out each piece, keeping the crumb.","Fill each hollow with hot curry, cap with the pulled bread and garnish with coriander."]'::jsonb,'Bunny chow has no rabbit in it — the name comes from Durban''s Banias merchants who first sold curry in hollowed loaves.',true),
('malva-pudding','Malva Pudding','A spongy, caramelized apricot pudding drenched in hot cream sauce — South Africa''s favourite dessert.','South African','Dessert','South Africa',ARRAY['Vegetarian'],'Dessert',50,'Easy',8,390,5,52,18,'[{"name":"Sugar","quantity":"200 g"},{"name":"Eggs","quantity":"2"},{"name":"Apricot jam","quantity":"2 tbsp"},{"name":"Flour","quantity":"150 g"},{"name":"Bicarbonate of soda","quantity":"1 tsp"},{"name":"Milk","quantity":"125 ml"},{"name":"Butter, melted","quantity":"2 tbsp"},{"name":"Vinegar","quantity":"1 tsp"},{"name":"Cream","quantity":"250 ml"},{"name":"Butter (sauce)","quantity":"100 g"},{"name":"Sugar (sauce)","quantity":"150 g"}]'::jsonb,'["Beat the sugar, eggs and jam until pale and fluffy.","Sift in the flour and bicarb, alternating with the milk.","Stir in the melted butter and vinegar.","Pour into a buttered baking dish and bake at 180°C for 35 minutes.","Meanwhile heat the cream, butter and sugar for the sauce until the butter melts.","Pour the hot sauce over the pudding as soon as it leaves the oven.","Let it soak in for 10 minutes and serve warm with custard."]'::jsonb,'Malva pudding is said to be named after a woman called Malva — or after the marsala wine once added to it. Nobody agrees.',true),
('beef-potjiekos','Beef Potjiekos','Slow-simmered beef and vegetables layered in a cast-iron potjie pot over coals — patience rewarded with deep flavour.','South African','Dinner','South Africa',ARRAY['Gluten-Free'],'Dinner',150,'Medium',6,480,38,30,20,'[{"name":"Beef chuck, cubed","quantity":"1.2 kg"},{"name":"Onions, quartered","quantity":"2"},{"name":"Carrots, chunked","quantity":"3"},{"name":"Baby potatoes","quantity":"500 g"},{"name":"Beef stock","quantity":"500 ml"},{"name":"Red wine","quantity":"125 ml"},{"name":"Tomato paste","quantity":"2 tbsp"},{"name":"Bay leaves","quantity":"2"},{"name":"Fresh thyme","quantity":"4 sprigs"},{"name":"Oil","quantity":"2 tbsp"},{"name":"Salt and pepper","quantity":"to taste"}]'::jsonb,'["Brown the beef in batches in the oiled potjie over hot coals.","Add the onions and fry until they catch some colour.","Pour in the wine and stock, stir in the tomato paste, bay and thyme.","Cover and simmer gently for 90 minutes — never stir a potjie.","Layer the carrots and potatoes on top, season, and cook 45 minutes more.","Serve straight from the pot with rice or crusty bread."]'::jsonb,'The golden rule of potjie: the layers are never stirred — each ingredient cooks in the steam of the one below it.',false),
('west-african-jollof-rice','West African Jollof Rice','Smoky, tomato-rich party rice cooked in one pot — the dish that fuels the friendliest food rivalry on earth.','West African','Dinner','Nigeria',ARRAY['Dairy-Free','Gluten-Free'],'Dinner',60,'Medium',6,410,12,68,12,'[{"name":"Long-grain rice","quantity":"400 g"},{"name":"Tomatoes","quantity":"4 large"},{"name":"Red bell peppers","quantity":"2"},{"name":"Scotch bonnet chili","quantity":"1"},{"name":"Onions","quantity":"2"},{"name":"Tomato paste","quantity":"3 tbsp"},{"name":"Chicken stock","quantity":"500 ml"},{"name":"Thyme and curry powder","quantity":"1 tsp each"},{"name":"Bay leaves","quantity":"2"},{"name":"Oil","quantity":"80 ml"},{"name":"Salt","quantity":"to taste"}]'::jsonb,'["Blend the tomatoes, peppers, chili and one onion into a smooth purée.","Fry the second onion (sliced) in oil until soft, add tomato paste and fry 3 minutes.","Add the purée and cook 15 minutes until reduced and darkened.","Season with thyme, curry, bay and salt.","Add the rinsed rice and stock, stir once, cover tightly with foil and a lid.","Cook on low heat 30–35 minutes until the rice is tender and smoky at the bottom.","Fluff and serve with fried plantain and grilled chicken."]'::jsonb,'The slight char at the bottom of the pot — party jollof smokiness — is the most prized part.',false),
('creamy-chicken-alfredo','Creamy Chicken Alfredo','Silky parmesan cream sauce clinging to ribbons of fettuccine with golden pan-seared chicken.','Italian','Dinner','Italy','{}','Dinner',30,'Easy',4,620,38,55,28,'[{"name":"Chicken breasts","quantity":"2"},{"name":"Fettuccine","quantity":"320 g"},{"name":"Butter","quantity":"60 g"},{"name":"Garlic cloves, minced","quantity":"3"},{"name":"Cream","quantity":"250 ml"},{"name":"Parmesan, grated","quantity":"80 g"},{"name":"Italian seasoning","quantity":"1 tsp"},{"name":"Parsley, chopped","quantity":"to garnish"},{"name":"Salt and pepper","quantity":"to taste"}]'::jsonb,'["Season the chicken and sear in a hot pan until golden and cooked through; rest and slice.","Cook the fettuccine in well-salted water; reserve a cup of pasta water.","Melt the butter in the pan, add garlic and cook 30 seconds.","Pour in the cream and simmer 3 minutes until slightly thick.","Off the heat, stir in the parmesan until melted.","Toss in the pasta with a splash of pasta water, top with sliced chicken and parsley."]'::jsonb,'Authentic Roman alfredo uses only butter and parmesan — the cream version is an American invention.',false),
('rainbow-buddha-bowl','Rainbow Buddha Bowl','A vibrant vegan bowl of roasted chickpeas, quinoa, avocado and crunchy slaw with tahini dressing.','Vegan','Lunch','International',ARRAY['Vegan','Gluten-Free','Dairy-Free'],'Lunch',35,'Easy',2,450,16,58,18,'[{"name":"Chickpeas, drained","quantity":"400 g tin"},{"name":"Quinoa","quantity":"150 g"},{"name":"Avocado","quantity":"1"},{"name":"Red cabbage, shredded","quantity":"100 g"},{"name":"Carrot, ribboned","quantity":"1"},{"name":"Cucumber, sliced","quantity":"1/2"},{"name":"Tahini","quantity":"3 tbsp"},{"name":"Lemon juice","quantity":"2 tbsp"},{"name":"Smoked paprika","quantity":"1 tsp"},{"name":"Olive oil","quantity":"2 tbsp"}]'::jsonb,'["Toss the chickpeas with oil, paprika and salt; roast at 200°C for 25 minutes.","Simmer the quinoa in double its volume of water for 15 minutes; fluff.","Whisk the tahini, lemon juice, a pinch of salt and enough water for a pourable dressing.","Build the bowls: quinoa base, then chickpeas, cabbage, carrot, cucumber and avocado.","Drizzle generously with tahini dressing."]'::jsonb,'The buddha bowl name refers to the rounded bowl resembling a buddha belly — piled high with abundance.',false),
('fluffy-buttermilk-pancakes','Fluffy Buttermilk Pancakes','Tall, cloud-soft pancakes with crisp golden edges — weekend mornings, sorted.','American','Breakfast','United States',ARRAY['Vegetarian'],'Breakfast',20,'Easy',4,380,10,58,11,'[{"name":"Flour","quantity":"250 g"},{"name":"Sugar","quantity":"2 tbsp"},{"name":"Baking powder","quantity":"2 tsp"},{"name":"Bicarbonate of soda","quantity":"1/2 tsp"},{"name":"Buttermilk","quantity":"300 ml"},{"name":"Eggs","quantity":"2"},{"name":"Melted butter","quantity":"40 g"},{"name":"Vanilla extract","quantity":"1 tsp"},{"name":"Salt","quantity":"1/2 tsp"}]'::jsonb,'["Whisk the dry ingredients in a large bowl.","Whisk the buttermilk, eggs, butter and vanilla in a jug.","Pour the wet into the dry and fold until just combined — lumps are good.","Rest the batter 5 minutes while a pan heats over medium.","Ladle in batter; flip when bubbles cover the surface.","Cook 1–2 minutes more until golden and puffed. Serve with syrup and berries."]'::jsonb,'Resting the batter lets the baking powder start working — that''s the secret to extra height.',false),
('greek-chicken-salad','Greek Chicken Salad','Lemony grilled chicken over crisp cucumber, tomatoes, olives and feta with oregano dressing.','Mediterranean','Lunch','Greece',ARRAY['Gluten-Free','High-Protein'],'Lunch',25,'Easy',2,390,35,12,22,'[{"name":"Chicken breasts","quantity":"2"},{"name":"Cucumber","quantity":"1"},{"name":"Cherry tomatoes","quantity":"200 g"},{"name":"Red onion","quantity":"1/2"},{"name":"Kalamata olives","quantity":"80 g"},{"name":"Feta","quantity":"100 g"},{"name":"Olive oil","quantity":"4 tbsp"},{"name":"Lemon","quantity":"1"},{"name":"Dried oregano","quantity":"2 tsp"},{"name":"Garlic clove","quantity":"1"}]'::jsonb,'["Marinate the chicken in half the olive oil, lemon juice, oregano and grated garlic for 10 minutes.","Grill or sear 5–6 minutes per side; rest, then slice.","Chop the cucumber, tomatoes and onion; toss with the olives.","Whisk the remaining oil and lemon with a pinch of oregano for the dressing.","Assemble the salad, top with chicken and crumbled feta, and dress."]'::jsonb,'In Greece the salad is horiatiki — village salad — and never contains lettuce.',false),
('smoky-beef-tacos','Smoky Beef Tacos','Chipotle-spiced beef mince in warm tortillas with lime crema and quick pickled onions.','Mexican','Dinner','Mexico',ARRAY['Dairy-Free option'],'Dinner',25,'Easy',4,480,28,40,22,'[{"name":"Beef mince","quantity":"500 g"},{"name":"Chipotle in adobo","quantity":"2 tbsp"},{"name":"Cumin","quantity":"1 tsp"},{"name":"Smoked paprika","quantity":"1 tsp"},{"name":"Corn tortillas","quantity":"8"},{"name":"Red onion, sliced","quantity":"1"},{"name":"Lime","quantity":"2"},{"name":"Sour cream","quantity":"120 ml"},{"name":"Fresh coriander","quantity":"a handful"},{"name":"Salt","quantity":"to taste"}]'::jsonb,'["Quick-pickle the onion in lime juice and a pinch of salt for 10 minutes.","Brown the mince, then stir in the chipotle, cumin, paprika and salt; cook 5 minutes.","Stir lime zest into the sour cream for a quick crema.","Warm the tortillas in a dry pan until pliable and lightly charred.","Fill with beef, pickled onions, crema and coriander."]'::jsonb,'Street tacos are always doubled up on tortillas — the second one catches the juices.',false),
('classic-banana-bread','Classic Banana Bread','Moist, tender loaf that puts overripe bananas to their highest use — with a crackly sugar top.','Baking','Snacks','International',ARRAY['Vegetarian'],'Snacks',65,'Easy',8,290,5,44,11,'[{"name":"Very ripe bananas","quantity":"3"},{"name":"Flour","quantity":"200 g"},{"name":"Sugar","quantity":"150 g"},{"name":"Butter, melted","quantity":"80 g"},{"name":"Eggs","quantity":"2"},{"name":"Bicarbonate of soda","quantity":"1 tsp"},{"name":"Vanilla extract","quantity":"1 tsp"},{"name":"Cinnamon","quantity":"1 tsp"},{"name":"Salt","quantity":"1/2 tsp"}]'::jsonb,'["Mash the bananas until almost smooth.","Whisk in the melted butter, sugar, eggs and vanilla.","Fold in the flour, bicarb, cinnamon and salt until just combined.","Pour into a lined loaf tin and sprinkle the top with a spoon of sugar.","Bake at 175°C for 55–60 minutes until a skewer comes out clean.","Cool in the tin 15 minutes before slicing."]'::jsonb,'Banana bread became popular in the 1930s as a thrifty way to rescue bananas during the Great Depression.',false)
